```dart
import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime dateTime;
  final double profitLoss; // positive for profit, negative for loss

  Transaction(this.coinName, this.dateTime, this.profitLoss);
}

List<String> topCoinsProfit({required List<Transaction> transactions, int numTop = 3}) {
  Map<String, double> profitMap = {};
  List<String> topCoins = [];

  for (var transaction in transactions) {
    if (profitMap.containsKey(transaction.coinName)) {
      profitMap[transaction.coinName]! += transaction.profitLoss;
    } else {
      profitMap[transaction.coinName] = transaction.profitLoss;
    }
  }

  var sortedProfits = profitMap.entries.map((e) => MapEntry(e.key, e.value / transactions.length));
  sortedProfits = sortedProfits.toList()..addAll(sortedProfits.take(numTop).reversed);

  for (var entry in sortedProfits) {
    topCoins.add(entry.key);
  }

  return topCoins;
}

