```javascript
function switchAdjectiveOrder(sentence) {
  // Split the sentence into words
  const words = sentence.split(' ');

  // Find all adjectives and store their indices
  const adjectives = [];
  let currentPartOfSpeech = null;
  for (let i = 0; i < words.length; i++) {
    const partOfSpeech = determinePartOfSpeech(words[i]);
    if (partOfSpeech === 'adjective') {
      if (currentPartOfSpeech !== null && currentPartOfSpeech !== partOfSpeech) {
        adjectives.push(i);
      }
      currentPartOfSpeech = partOfSpeech;
    } else {
      currentPartOfSpeech = null;
    }
  }

  // Switch the positions of adjacent adjectives
  for (let i = 0; i < adjectives.length; i++) {
    const j = adjectives[i] - 1;
    [words[j], words[adjectives[i]]] = [words[adjectives[i]], words[j]];
  }

  // Join the words back into a sentence
  return words.join(' ') + '.';
}

// Helper function to determine the part of speech of a word
function determinePartOfSpeech(word) {
  const tag = posTagger(word)[0][0].toUpperCase();
  return tag.startsWith('JJ') ? 'adjective' : tag;
}

// Dependency: You need a library like natural or compromise to perform Part-of-Speech Tagging (POS tagging).
// Install it using npm: `npm install natural` or `yarn add natural`, then require it at the beginning of your file: `const natural = require('natural');`
// Then replace `posTagger` with `new natural.BrillPOSTagger().tag()`
```

