 I'd be happy to help you create a basic REST service wrapper class in C# with authentication token handling. This example uses the `HttpClient` class from the `System.Net.Http` namespace and includes a simple interface for making GET, POST, PUT, and DELETE requests. The class also includes methods for setting and getting an access token.

```csharp using System;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;

public class RestServiceWrapper
{
    private readonly HttpClient _httpClient;
    private string _accessToken;

    public RestServiceWrapper(string baseAddress)
    {
        _httpClient = new HttpClient { BaseAddress = new Uri(baseAddress) };
    }

    public void SetAccessToken(string accessToken)
    {
        _accessToken = accessToken;
        _httpClient.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", _accessToken);
    }

    public async Task<string> GetAsync(string requestUri)
    {
        using (var response = await _httpClient.GetAsync(requestUri))
        {
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsStringAsync();
        }
    }

    public async Task<string> PostAsync(string requestUri, StringContent content)
    {
        using (var response = await _httpClient.PostAsync(requestUri, content))
        {
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsStringAsync();
        }
    }

    public async Task<string> PutAsync(string requestUri, StringContent content)
    {
        using (var response = await _httpClient.PutAsync(requestUri, content))
        {
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsStringAsync();
        }
    }

    public async Task DeleteAsync(string requestUri)
    {
        using (var response = await _httpClient.DeleteAsync(requestUri))
        {
            response.EnsureSuccessStatusCode();
        }
    }
}
